import { randomUUID } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';

const MAX_SAFE = Number.MAX_SAFE_INTEGER;

function fail(code, message) {
  const error = new Error(message);
  error.code = code;
  throw error;
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function hasExactKeys(value, expected) {
  if (!isRecord(value)) return false;
  const keys = Object.keys(value).sort();
  return keys.length === expected.length
    && keys.every((key, index) => key === expected[index]);
}

function requireExact(value, keys) {
  const expected = [...keys].sort();
  if (!hasExactKeys(value, expected)) fail('VALIDATION', 'Invalid input');
}

function requireString(value) {
  if (typeof value !== 'string' || value.length === 0) {
    fail('VALIDATION', 'Expected a nonempty string');
  }
}

function requireInteger(value, minimum = 0) {
  if (!Number.isSafeInteger(value) || value < minimum) {
    fail('VALIDATION', 'Expected a safe integer');
  }
}

function authorize(actor, mutate = false) {
  if (!hasExactKeys(actor, ['role', 'tenant'])
      || typeof actor.tenant !== 'string' || actor.tenant.length === 0
      || (actor.role !== 'admin' && actor.role !== 'reader')) {
    fail('AUTH', 'Invalid actor');
  }
  if (mutate && actor.role !== 'admin') fail('FORBIDDEN', 'Mutation is forbidden');
}

function reservation(row) {
  return {
    id: row.id,
    tenant: row.tenant,
    sku: row.sku,
    quantity: row.quantity,
    amountCents: row.amount_cents,
    status: row.status,
    version: row.version,
  };
}

function inventoryItem(row) {
  return { sku: row.sku, available: row.available, unitCents: row.unit_cents };
}

export class ReservationService {
  #db;

  constructor(filename) {
    this.#db = new DatabaseSync(filename);
    this.#db.exec(`
      PRAGMA busy_timeout = 5000;
      CREATE TABLE IF NOT EXISTS reservation_inventory (
        tenant TEXT NOT NULL,
        sku TEXT NOT NULL,
        available INTEGER NOT NULL,
        unit_cents INTEGER NOT NULL,
        PRIMARY KEY (tenant, sku)
      ) STRICT;
      CREATE TABLE IF NOT EXISTS reservation_resources (
        sequence INTEGER PRIMARY KEY AUTOINCREMENT,
        id TEXT NOT NULL UNIQUE,
        tenant TEXT NOT NULL,
        sku TEXT NOT NULL,
        quantity INTEGER NOT NULL,
        amount_cents INTEGER NOT NULL,
        status TEXT NOT NULL,
        version INTEGER NOT NULL
      ) STRICT;
      CREATE INDEX IF NOT EXISTS reservation_resources_tenant_sequence
        ON reservation_resources (tenant, sequence);
      CREATE TABLE IF NOT EXISTS reservation_idempotency (
        tenant TEXT NOT NULL,
        operation TEXT NOT NULL,
        key TEXT NOT NULL,
        canonical_input TEXT NOT NULL,
        result TEXT NOT NULL,
        PRIMARY KEY (tenant, operation, key)
      ) STRICT;
    `);
  }

  #transaction(action) {
    let began = false;
    try {
      this.#db.exec('BEGIN IMMEDIATE');
      began = true;
      const result = action();
      this.#db.exec('COMMIT');
      return result;
    } catch (error) {
      if (began) {
        try { this.#db.exec('ROLLBACK'); } catch { /* preserve the original error */ }
      }
      throw error;
    }
  }

  #replay(tenant, operation, key, canonicalInput) {
    const row = this.#db.prepare(`
      SELECT canonical_input, result
      FROM reservation_idempotency
      WHERE tenant = ? AND operation = ? AND key = ?
    `).get(tenant, operation, key);
    if (!row) return undefined;
    if (row.canonical_input !== canonicalInput) fail('CONFLICT', 'Idempotency key conflict');
    return JSON.parse(row.result);
  }

  #remember(tenant, operation, key, canonicalInput, result) {
    this.#db.prepare(`
      INSERT INTO reservation_idempotency
        (tenant, operation, key, canonical_input, result)
      VALUES (?, ?, ?, ?, ?)
    `).run(tenant, operation, key, canonicalInput, JSON.stringify(result));
  }

  seed(actor, input) {
    authorize(actor, true);
    requireExact(input, ['sku', 'available', 'unitCents']);
    requireString(input.sku);
    requireInteger(input.available);
    requireInteger(input.unitCents);

    return this.#transaction(() => {
      const existing = this.#db.prepare(`
        SELECT 1 FROM reservation_inventory WHERE tenant = ? AND sku = ?
      `).get(actor.tenant, input.sku);
      if (existing) fail('CONFLICT', 'SKU already exists');
      this.#db.prepare(`
        INSERT INTO reservation_inventory (tenant, sku, available, unit_cents)
        VALUES (?, ?, ?, ?)
      `).run(actor.tenant, input.sku, input.available, input.unitCents);
    });
  }

  reserve(actor, input) {
    authorize(actor, true);
    requireExact(input, ['key', 'sku', 'quantity']);
    requireString(input.key);
    requireString(input.sku);
    requireInteger(input.quantity, 1);
    const canonicalInput = JSON.stringify({ sku: input.sku, quantity: input.quantity });

    return this.#transaction(() => {
      const replay = this.#replay(actor.tenant, 'reserve', input.key, canonicalInput);
      if (replay !== undefined) return replay;

      const stock = this.#db.prepare(`
        SELECT sku, available, unit_cents
        FROM reservation_inventory
        WHERE tenant = ? AND sku = ?
      `).get(actor.tenant, input.sku);
      if (!stock) fail('NOT_FOUND', 'SKU not found');
      if (stock.available < input.quantity) fail('CONFLICT', 'Insufficient inventory');
      if (stock.unit_cents !== 0 && input.quantity > Math.floor(MAX_SAFE / stock.unit_cents)) {
        fail('VALIDATION', 'Amount exceeds the safe integer range');
      }

      const result = {
        id: randomUUID(),
        tenant: actor.tenant,
        sku: input.sku,
        quantity: input.quantity,
        amountCents: input.quantity * stock.unit_cents,
        status: 'reserved',
        version: 1,
      };
      this.#db.prepare(`
        UPDATE reservation_inventory
        SET available = available - ?
        WHERE tenant = ? AND sku = ?
      `).run(input.quantity, actor.tenant, input.sku);
      this.#db.prepare(`
        INSERT INTO reservation_resources
          (id, tenant, sku, quantity, amount_cents, status, version)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).run(result.id, result.tenant, result.sku, result.quantity,
        result.amountCents, result.status, result.version);
      this.#remember(actor.tenant, 'reserve', input.key, canonicalInput, result);
      return result;
    });
  }

  cancel(actor, input) {
    authorize(actor, true);
    requireExact(input, ['key', 'id', 'expectedVersion']);
    requireString(input.key);
    requireString(input.id);
    requireInteger(input.expectedVersion, 1);
    const canonicalInput = JSON.stringify({ id: input.id, expectedVersion: input.expectedVersion });

    return this.#transaction(() => {
      const replay = this.#replay(actor.tenant, 'cancel', input.key, canonicalInput);
      if (replay !== undefined) return replay;

      const row = this.#db.prepare(`
        SELECT id, tenant, sku, quantity, amount_cents, status, version
        FROM reservation_resources
        WHERE tenant = ? AND id = ?
      `).get(actor.tenant, input.id);
      if (!row) fail('NOT_FOUND', 'Reservation not found');
      if (row.version !== input.expectedVersion || row.status !== 'reserved') {
        fail('CONFLICT', 'Reservation cannot be canceled');
      }

      this.#db.prepare(`
        UPDATE reservation_resources SET status = 'canceled', version = version + 1
        WHERE tenant = ? AND id = ?
      `).run(actor.tenant, input.id);
      this.#db.prepare(`
        UPDATE reservation_inventory SET available = available + ?
        WHERE tenant = ? AND sku = ?
      `).run(row.quantity, actor.tenant, row.sku);
      const result = reservation({ ...row, status: 'canceled', version: row.version + 1 });
      this.#remember(actor.tenant, 'cancel', input.key, canonicalInput, result);
      return result;
    });
  }

  inventory(actor, sku) {
    authorize(actor);
    requireString(sku);
    const row = this.#db.prepare(`
      SELECT sku, available, unit_cents
      FROM reservation_inventory
      WHERE tenant = ? AND sku = ?
    `).get(actor.tenant, sku);
    if (!row) fail('NOT_FOUND', 'SKU not found');
    return inventoryItem(row);
  }

  get(actor, id) {
    authorize(actor);
    requireString(id);
    const row = this.#db.prepare(`
      SELECT id, tenant, sku, quantity, amount_cents, status, version
      FROM reservation_resources
      WHERE tenant = ? AND id = ?
    `).get(actor.tenant, id);
    if (!row) fail('NOT_FOUND', 'Reservation not found');
    return reservation(row);
  }

  list(actor, input) {
    authorize(actor);
    requireExact(input, ['page', 'pageSize']);
    requireInteger(input.page, 1);
    requireInteger(input.pageSize, 1);
    if (input.pageSize > 50) fail('VALIDATION', 'pageSize must not exceed 50');

    const total = this.#db.prepare(`
      SELECT COUNT(*) AS total FROM reservation_resources WHERE tenant = ?
    `).get(actor.tenant).total;
    if (input.page - 1 > Math.floor(MAX_SAFE / input.pageSize)) return { items: [], total };
    const offset = (input.page - 1) * input.pageSize;
    const rows = this.#db.prepare(`
      SELECT id, tenant, sku, quantity, amount_cents, status, version
      FROM reservation_resources
      WHERE tenant = ?
      ORDER BY sequence
      LIMIT ? OFFSET ?
    `).all(actor.tenant, input.pageSize, offset);
    return { items: rows.map(reservation), total };
  }

  close() {
    this.#db.close();
  }
}

