import { DatabaseSync } from 'node:sqlite';

const MAX_SAFE = Number.MAX_SAFE_INTEGER;

function fail(code, message) {
  const error = new Error(message);
  error.code = code;
  throw error;
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function hasExactKeys(value, expected) {
  if (!isRecord(value)) return false;
  const keys = Object.keys(value).sort();
  return keys.length === expected.length
    && keys.every((key, index) => key === expected[index]);
}

function requireExact(value, keys) {
  const expected = [...keys].sort();
  if (!hasExactKeys(value, expected)) fail('VALIDATION', 'Invalid input');
}

function requireString(value) {
  if (typeof value !== 'string' || value.length === 0) {
    fail('VALIDATION', 'Expected a nonempty string');
  }
}

function requireInteger(value, minimum = 0) {
  if (!Number.isSafeInteger(value) || value < minimum) {
    fail('VALIDATION', 'Expected a safe integer');
  }
}

function authorize(actor, mutate = false) {
  if (!hasExactKeys(actor, ['role', 'tenant'])
      || typeof actor.tenant !== 'string' || actor.tenant.length === 0
      || (actor.role !== 'admin' && actor.role !== 'reader')) {
    fail('AUTH', 'Invalid actor');
  }
  if (mutate && actor.role !== 'admin') fail('FORBIDDEN', 'Mutation is forbidden');
}

function invoice(row) {
  return {
    id: row.id,
    tenant: row.tenant,
    reservationId: row.reservation_id,
    amountCents: row.amount_cents,
    status: row.status,
    version: row.version,
  };
}

function validateEvent(event, actorTenant) {
  requireExact(event, ['id', 'tenant', 'sku', 'quantity', 'amountCents', 'status', 'version']);
  requireString(event.id);
  requireString(event.tenant);
  requireString(event.sku);
  requireInteger(event.quantity, 1);
  requireInteger(event.amountCents);
  if (event.status !== 'reserved') fail('VALIDATION', 'Event is not reserved');
  requireInteger(event.version, 1);
  if (event.tenant !== actorTenant) fail('FORBIDDEN', 'Event tenant mismatch');
}

export class BillingService {
  #db;

  constructor(filename) {
    this.#db = new DatabaseSync(filename);
    this.#db.exec(`
      PRAGMA busy_timeout = 5000;
      CREATE TABLE IF NOT EXISTS billing_invoices (
        sequence INTEGER PRIMARY KEY AUTOINCREMENT,
        id TEXT NOT NULL UNIQUE,
        tenant TEXT NOT NULL,
        reservation_id TEXT NOT NULL,
        amount_cents INTEGER NOT NULL,
        status TEXT NOT NULL,
        version INTEGER NOT NULL,
        UNIQUE (tenant, reservation_id)
      ) STRICT;
      CREATE INDEX IF NOT EXISTS billing_invoices_tenant_sequence
        ON billing_invoices (tenant, sequence);
      CREATE TABLE IF NOT EXISTS billing_idempotency (
        tenant TEXT NOT NULL,
        operation TEXT NOT NULL,
        key TEXT NOT NULL,
        canonical_input TEXT NOT NULL,
        result TEXT NOT NULL,
        PRIMARY KEY (tenant, operation, key)
      ) STRICT;
    `);
  }

  #transaction(action) {
    let began = false;
    try {
      this.#db.exec('BEGIN IMMEDIATE');
      began = true;
      const result = action();
      this.#db.exec('COMMIT');
      return result;
    } catch (error) {
      if (began) {
        try { this.#db.exec('ROLLBACK'); } catch { /* preserve the original error */ }
      }
      throw error;
    }
  }

  #replay(tenant, operation, key, canonicalInput) {
    const row = this.#db.prepare(`
      SELECT canonical_input, result
      FROM billing_idempotency
      WHERE tenant = ? AND operation = ? AND key = ?
    `).get(tenant, operation, key);
    if (!row) return undefined;
    if (row.canonical_input !== canonicalInput) fail('CONFLICT', 'Idempotency key conflict');
    return JSON.parse(row.result);
  }

  #remember(tenant, operation, key, canonicalInput, result) {
    this.#db.prepare(`
      INSERT INTO billing_idempotency
        (tenant, operation, key, canonical_input, result)
      VALUES (?, ?, ?, ?, ?)
    `).run(tenant, operation, key, canonicalInput, JSON.stringify(result));
  }

  issue(actor, input) {
    authorize(actor, true);
    requireExact(input, ['key', 'event']);
    requireString(input.key);
    validateEvent(input.event, actor.tenant);
    const event = input.event;
    const canonicalInput = JSON.stringify({
      event: {
        id: event.id,
        tenant: event.tenant,
        sku: event.sku,
        quantity: event.quantity,
        amountCents: event.amountCents,
        status: event.status,
        version: event.version,
      },
    });

    return this.#transaction(() => {
      const replay = this.#replay(actor.tenant, 'issue', input.key, canonicalInput);
      if (replay !== undefined) return replay;

      const existing = this.#db.prepare(`
        SELECT 1 FROM billing_invoices WHERE tenant = ? AND reservation_id = ?
      `).get(actor.tenant, event.id);
      if (existing) fail('CONFLICT', 'Reservation already invoiced');

      const result = {
        id: randomUUID(),
        tenant: actor.tenant,
        reservationId: event.id,
        amountCents: event.amountCents,
        status: 'open',
        version: 1,
      };
      this.#db.prepare(`
        INSERT INTO billing_invoices
          (id, tenant, reservation_id, amount_cents, status, version)
        VALUES (?, ?, ?, ?, ?, ?)
      `).run(result.id, result.tenant, result.reservationId,
        result.amountCents, result.status, result.version);
      this.#remember(actor.tenant, 'issue', input.key, canonicalInput, result);
      return result;
    });
  }

  pay(actor, input) {
    return this.#transition(actor, input, 'pay', 'open', 'paid');
  }

  refund(actor, input) {
    return this.#transition(actor, input, 'refund', 'paid', 'refunded');
  }

  #transition(actor, input, operation, fromStatus, toStatus) {
    authorize(actor, true);
    requireExact(input, ['key', 'id', 'expectedVersion']);
    requireString(input.key);
    requireString(input.id);
    requireInteger(input.expectedVersion, 1);
    const canonicalInput = JSON.stringify({ id: input.id, expectedVersion: input.expectedVersion });

    return this.#transaction(() => {
      const replay = this.#replay(actor.tenant, operation, input.key, canonicalInput);
      if (replay !== undefined) return replay;

      const row = this.#db.prepare(`
        SELECT id, tenant, reservation_id, amount_cents, status, version
        FROM billing_invoices
        WHERE tenant = ? AND id = ?
      `).get(actor.tenant, input.id);
      if (!row) fail('NOT_FOUND', 'Invoice not found');
      if (row.version !== input.expectedVersion || row.status !== fromStatus) {
        fail('CONFLICT', 'Invoice cannot make this transition');
      }

      this.#db.prepare(`
        UPDATE billing_invoices SET status = ?, version = version + 1
        WHERE tenant = ? AND id = ?
      `).run(toStatus, actor.tenant, input.id);
      const result = invoice({ ...row, status: toStatus, version: row.version + 1 });
      this.#remember(actor.tenant, operation, input.key, canonicalInput, result);
      return result;
    });
  }

  get(actor, id) {
    authorize(actor);
    requireString(id);
    const row = this.#db.prepare(`
      SELECT id, tenant, reservation_id, amount_cents, status, version
      FROM billing_invoices
      WHERE tenant = ? AND id = ?
    `).get(actor.tenant, id);
    if (!row) fail('NOT_FOUND', 'Invoice not found');
    return invoice(row);
  }

  list(actor, input) {
    authorize(actor);
    requireExact(input, ['page', 'pageSize']);
    requireInteger(input.page, 1);
    requireInteger(input.pageSize, 1);
    if (input.pageSize > 50) fail('VALIDATION', 'pageSize must not exceed 50');

    const total = this.#db.prepare(`
      SELECT COUNT(*) AS total FROM billing_invoices WHERE tenant = ?
    `).get(actor.tenant).total;
    if (input.page - 1 > Math.floor(MAX_SAFE / input.pageSize)) return { items: [], total };
    const offset = (input.page - 1) * input.pageSize;
    const rows = this.#db.prepare(`
      SELECT id, tenant, reservation_id, amount_cents, status, version
      FROM billing_invoices
      WHERE tenant = ?
      ORDER BY sequence
      LIMIT ? OFFSET ?
    `).all(actor.tenant, input.pageSize, offset);
    return { items: rows.map(invoice), total };
  }

  close() {
    this.#db.close();
  }
}

