    const canonicalInput = JSON.stringify({ id: input.id, expectedVersion: input.expectedVersion });

    return this.#transaction(() => {
      const replay = this.#replay(actor.tenant, 'cancel', input.key, canonicalInput);
      if (replay !== undefined) return replay;

      const row = this.#db.prepare(`
        SELECT id, tenant, sku, quantity, amount_cents, status, version
        FROM reservation_resources
        WHERE tenant = ? AND id = ?
      `).get(actor.tenant, input.id);
      if (!row) fail('NOT_FOUND', 'Reservation not found');
      if (row.version !== input.expectedVersion || row.status !== 'reserved') {
        fail('CONFLICT', 'Reservation cannot be canceled');
      }

      this.#db.prepare(`
        UPDATE reservation_resources SET status = 'canceled', version = version + 1
        WHERE tenant = ? AND id = ?
      `).run(actor.tenant, input.id);
      this.#db.prepare(`
        UPDATE reservation_inventory SET available = available + ?
        WHERE tenant = ? AND sku = ?
      `).run(row.quantity, actor.tenant, row.sku);
      const result = reservation({ ...row, status: 'canceled', version: row.version + 1 });
      this.#remember(actor.tenant, 'cancel', input.key, canonicalInput, result);
      return result;
    });
  }

  inventory(actor, sku) {
    authorize(actor);
    requireString(sku);
    const row = this.#db.prepare(`
      SELECT sku, available, unit_cents
      FROM reservation_inventory
      WHERE tenant = ? AND sku = ?
    `).get(actor.tenant, sku);
    if (!row) fail('NOT_FOUND', 'SKU not found');
    return inventoryItem(row);
  }

  get(actor, id) {
    authorize(actor);
    requireString(id);
    const row = this.#db.prepare(`
      SELECT id, tenant, sku, quantity, amount_cents, status, version
      FROM reservation_resources
      WHERE tenant = ? AND id = ?
    `).get(actor.tenant, id);
    if (!row) fail('NOT_FOUND', 'Reservation not found');
    return reservation(row);
  }

  list(actor, input) {
    authorize(actor);
    requireExact(input, ['page', 'pageSize']);
    requireInteger(input.page, 1);
    requireInteger(input.pageSize, 1);
    if (input.pageSize > 50) fail('VALIDATION', 'pageSize must not exceed 50');

    const total = this.#db.prepare(`
      SELECT COUNT(*) AS total FROM reservation_resources WHERE tenant = ?
    `).get(actor.tenant).total;
    if (input.page - 1 > Math.floor(MAX_SAFE / input.pageSize)) return { items: [], total };
    const offset = (input.page - 1) * input.pageSize;
    const rows = this.#db.prepare(`
      SELECT id, tenant, sku, quantity, amount_cents, status, version
      FROM reservation_resources
      WHERE tenant = ?
      ORDER BY sequence
      LIMIT ? OFFSET ?
    `).all(actor.tenant, input.pageSize, offset);
    return { items: rows.map(reservation), total };
  }

  close() {
    this.#db.close();
  }
}

