import { randomUUID } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';

function fail(code, message) {
  const error = new Error(message);
  error.code = code;
  throw error;
}

function isRecord(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function hasExactKeys(value, expected) {
  if (!isRecord(value)) return false;
  const keys = Reflect.ownKeys(value);
  if (keys.length !== expected.length || keys.some((key) => typeof key !== 'string')) return false;
  const actual = new Set(keys);
  return expected.every((key) => actual.has(key));
}

function isNonemptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function isSafeIntegerAtLeast(value, minimum) {
  return Number.isSafeInteger(value) && value >= minimum;
}

function authorize(actor, mayMutate) {
  if (!hasExactKeys(actor, ['tenant', 'role']) ||
      !isNonemptyString(actor.tenant) ||
      (actor.role !== 'admin' && actor.role !== 'reader')) {
    fail('AUTH', 'Invalid actor');
  }
  if (mayMutate && actor.role !== 'admin') fail('FORBIDDEN', 'Mutation requires admin role');
}

function validateSeedInput(input) {
  if (!hasExactKeys(input, ['sku', 'available', 'unitCents']) ||
      !isNonemptyString(input.sku) ||
      !isSafeIntegerAtLeast(input.available, 0) ||
      !isSafeIntegerAtLeast(input.unitCents, 0)) {
    fail('VALIDATION', 'Invalid seed input');
  }
}

function validateReserveInput(input) {
  if (!hasExactKeys(input, ['key', 'sku', 'quantity']) ||
      !isNonemptyString(input.key) ||
      !isNonemptyString(input.sku) ||
      !isSafeIntegerAtLeast(input.quantity, 1)) {
    fail('VALIDATION', 'Invalid reserve input');
  }
}

function validateCancelInput(input) {
  if (!hasExactKeys(input, ['key', 'id', 'expectedVersion']) ||
      !isNonemptyString(input.key) ||
      !isNonemptyString(input.id) ||
      !isSafeIntegerAtLeast(input.expectedVersion, 1)) {
    fail('VALIDATION', 'Invalid cancel input');
  }
}

function validateListInput(input) {
  if (!hasExactKeys(input, ['page', 'pageSize']) ||
      !isSafeIntegerAtLeast(input.page, 1) ||
      !isSafeIntegerAtLeast(input.pageSize, 1) ||
      input.pageSize > 50) {
    fail('VALIDATION', 'Invalid list input');
  }
}

function validateIdentifier(value, name) {
  if (!isNonemptyString(value)) fail('VALIDATION', `Invalid ${name}`);
}

function publicReservation(row) {
  return {
    id: row.id,
    tenant: row.tenant,
    sku: row.sku,
    quantity: row.quantity,
    amountCents: row.amount_cents,
    status: row.status,
    version: row.version,
  };
}

export class ReservationService {
  #database;

  constructor(filename) {
    this.#database = new DatabaseSync(filename);
    this.#database.exec('PRAGMA busy_timeout = 5000');
    this.#database.exec(`
      CREATE TABLE IF NOT EXISTS reservation_inventory (
        tenant TEXT NOT NULL,
        sku TEXT NOT NULL,
        available INTEGER NOT NULL,
        unit_cents INTEGER NOT NULL,
        PRIMARY KEY (tenant, sku)
      ) STRICT;
      CREATE TABLE IF NOT EXISTS reservation_records (
        creation_order INTEGER PRIMARY KEY AUTOINCREMENT,
        id TEXT NOT NULL UNIQUE,
        tenant TEXT NOT NULL,
        sku TEXT NOT NULL,
        quantity INTEGER NOT NULL,
        amount_cents INTEGER NOT NULL,
        status TEXT NOT NULL,
        version INTEGER NOT NULL
      ) STRICT;
      CREATE INDEX IF NOT EXISTS reservation_records_tenant_order
        ON reservation_records (tenant, creation_order);
      CREATE TABLE IF NOT EXISTS reservation_idempotency (
        tenant TEXT NOT NULL,
        operation TEXT NOT NULL,
        idem_key TEXT NOT NULL,
        canonical_input TEXT NOT NULL,
        result_json TEXT NOT NULL,
        PRIMARY KEY (tenant, operation, idem_key)
      ) STRICT;
    `);
  }

  #transaction(action) {
    this.#database.exec('BEGIN IMMEDIATE');
    try {
      const result = action();
      this.#database.exec('COMMIT');
      return result;
    } catch (error) {
      try { this.#database.exec('ROLLBACK'); } catch { /* Preserve the original error. */ }
      throw error;
    }
  }

  #replayOrConflict(tenant, operation, key, canonicalInput) {
    const record = this.#database.prepare(`
      SELECT canonical_input, result_json FROM reservation_idempotency
      WHERE tenant = ? AND operation = ? AND idem_key = ?
    `).get(tenant, operation, key);
    if (!record) return undefined;
    if (record.canonical_input !== canonicalInput) fail('CONFLICT', 'Idempotency key input differs');
    return JSON.parse(record.result_json);
  }

  #remember(tenant, operation, key, canonicalInput, result) {
    this.#database.prepare(`
      INSERT INTO reservation_idempotency
        (tenant, operation, idem_key, canonical_input, result_json)
      VALUES (?, ?, ?, ?, ?)
    `).run(tenant, operation, key, canonicalInput, JSON.stringify(result));
  }

  seed(actor, input) {
    authorize(actor, true);
    validateSeedInput(input);
    return this.#transaction(() => {
      if (this.#database.prepare(`
        SELECT 1 FROM reservation_inventory WHERE tenant = ? AND sku = ?
      `).get(actor.tenant, input.sku)) fail('CONFLICT', 'SKU already exists');
      this.#database.prepare(`
        INSERT INTO reservation_inventory (tenant, sku, available, unit_cents)
        VALUES (?, ?, ?, ?)
      `).run(actor.tenant, input.sku, input.available, input.unitCents);
    });
  }

  reserve(actor, input) {
    authorize(actor, true);
    validateReserveInput(input);
    const canonicalInput = JSON.stringify({ key: input.key, sku: input.sku, quantity: input.quantity });
    return this.#transaction(() => {
      const replay = this.#replayOrConflict(actor.tenant, 'reserve', input.key, canonicalInput);
      if (replay !== undefined) return replay;
      const inventory = this.#database.prepare(`
        SELECT available, unit_cents FROM reservation_inventory
        WHERE tenant = ? AND sku = ?
      `).get(actor.tenant, input.sku);
      if (!inventory) fail('NOT_FOUND', 'SKU not found');
      if (inventory.available < input.quantity) fail('CONFLICT', 'Insufficient inventory');
      const amountCents = input.quantity * inventory.unit_cents;
      if (!Number.isSafeInteger(amountCents)) fail('VALIDATION', 'Reservation amount is unsafe');
      const result = {
        id: randomUUID(), tenant: actor.tenant, sku: input.sku, quantity: input.quantity,
        amountCents, status: 'reserved', version: 1,
      };
      this.#database.prepare(`
        UPDATE reservation_inventory SET available = available - ?
        WHERE tenant = ? AND sku = ?
      `).run(input.quantity, actor.tenant, input.sku);
      this.#database.prepare(`
        INSERT INTO reservation_records
          (id, tenant, sku, quantity, amount_cents, status, version)
        VALUES (?, ?, ?, ?, ?, 'reserved', 1)
      `).run(result.id, actor.tenant, input.sku, input.quantity, amountCents);
      this.#remember(actor.tenant, 'reserve', input.key, canonicalInput, result);
      return result;
    });
  }

  cancel(actor, input) {
    authorize(actor, true);
    validateCancelInput(input);
    const canonicalInput = JSON.stringify({ key: input.key, id: input.id, expectedVersion: input.expectedVersion });
    return this.#transaction(() => {
      const replay = this.#replayOrConflict(actor.tenant, 'cancel', input.key, canonicalInput);
      if (replay !== undefined) return replay;
      const row = this.#database.prepare(`
        SELECT id, tenant, sku, quantity, amount_cents, status, version
        FROM reservation_records WHERE tenant = ? AND id = ?
      `).get(actor.tenant, input.id);
      if (!row) fail('NOT_FOUND', 'Reservation not found');
      if (row.version !== input.expectedVersion || row.status !== 'reserved') {
        fail('CONFLICT', 'Reservation cannot be canceled');
      }
      const nextVersion = row.version + 1;
      if (!Number.isSafeInteger(nextVersion)) fail('VALIDATION', 'Reservation version is unsafe');
      this.#database.prepare(`
        UPDATE reservation_records SET status = 'canceled', version = ?
        WHERE tenant = ? AND id = ?
      `).run(nextVersion, actor.tenant, input.id);
      this.#database.prepare(`
        UPDATE reservation_inventory SET available = available + ?
        WHERE tenant = ? AND sku = ?
      `).run(row.quantity, actor.tenant, row.sku);
      const result = {
        id: row.id, tenant: row.tenant, sku: row.sku, quantity: row.quantity,
        amountCents: row.amount_cents, status: 'canceled', version: nextVersion,
      };
      this.#remember(actor.tenant, 'cancel', input.key, canonicalInput, result);
      return result;
    });
  }

  inventory(actor, sku) {
    authorize(actor, false);
    validateIdentifier(sku, 'SKU');
    const row = this.#database.prepare(`
      SELECT sku, available, unit_cents FROM reservation_inventory
      WHERE tenant = ? AND sku = ?
    `).get(actor.tenant, sku);
    if (!row) fail('NOT_FOUND', 'SKU not found');
    return { sku: row.sku, available: row.available, unitCents: row.unit_cents };
  }

  get(actor, id) {
    authorize(actor, false);
    validateIdentifier(id, 'reservation ID');
    const row = this.#database.prepare(`
      SELECT id, tenant, sku, quantity, amount_cents, status, version
      FROM reservation_records WHERE tenant = ? AND id = ?
    `).get(actor.tenant, id);
    if (!row) fail('NOT_FOUND', 'Reservation not found');
    return publicReservation(row);
  }

  list(actor, input) {
    authorize(actor, false);
    validateListInput(input);
    const { total } = this.#database.prepare(`
      SELECT COUNT(*) AS total FROM reservation_records WHERE tenant = ?
    `).get(actor.tenant);
    if (total === 0 || input.page > Math.floor((total - 1) / input.pageSize) + 1) {
      return { items: [], total };
    }
    const offset = (input.page - 1) * input.pageSize;
    const rows = this.#database.prepare(`
      SELECT id, tenant, sku, quantity, amount_cents, status, version
      FROM reservation_records WHERE tenant = ?
      ORDER BY creation_order LIMIT ? OFFSET ?
    `).all(actor.tenant, input.pageSize, offset);
    return { items: rows.map(publicReservation), total };
  }

  close() {
    this.#database.close();
  }
}

