import {randomUUID} from 'node:crypto';
import {DatabaseSync} from 'node:sqlite';

const EVENT_KEYS = ['amountCents', 'id', 'quantity', 'sku', 'status', 'tenant', 'version'];
const ISSUE_KEYS = ['event', 'key'];
const TRANSITION_KEYS = ['expectedVersion', 'id', 'key'];
const PAGE_KEYS = ['page', 'pageSize'];

function failure(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function hasExactKeys(value, expected) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const keys = Reflect.ownKeys(value);
  return keys.length === expected.length
    && keys.every((key) => typeof key === 'string' && expected.includes(key));
}

function nonemptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function positiveSafeInteger(value) {
  return Number.isSafeInteger(value) && value > 0;
}

function nonnegativeSafeInteger(value) {
  return Number.isSafeInteger(value) && value >= 0;
}

function validateActor(actor) {
  if (!hasExactKeys(actor, ['role', 'tenant'])
      || !nonemptyString(actor.tenant)
      || (actor.role !== 'admin' && actor.role !== 'reader')) {
    throw failure('AUTH', 'Invalid actor');
  }
}

function authorizeMutation(actor) {
  validateActor(actor);
  if (actor.role !== 'admin') throw failure('FORBIDDEN', 'Mutation is not allowed');
}

function validateIssueInput(input) {
  if (!hasExactKeys(input, ISSUE_KEYS) || !nonemptyString(input.key)) {
    throw failure('VALIDATION', 'Invalid issue input');
  }
  const event = input.event;
  if (!hasExactKeys(event, EVENT_KEYS)
      || !nonemptyString(event.id)
      || !nonemptyString(event.tenant)
      || !nonemptyString(event.sku)
      || !positiveSafeInteger(event.quantity)
      || !nonnegativeSafeInteger(event.amountCents)
      || event.status !== 'reserved'
      || !positiveSafeInteger(event.version)) {
    throw failure('VALIDATION', 'Invalid reservation event');
  }
}

function validateTransitionInput(input) {
  if (!hasExactKeys(input, TRANSITION_KEYS)
      || !nonemptyString(input.key)
      || !nonemptyString(input.id)
      || !positiveSafeInteger(input.expectedVersion)) {
    throw failure('VALIDATION', 'Invalid transition input');
  }
}

function validateListInput(input) {
  if (!hasExactKeys(input, PAGE_KEYS)
      || !positiveSafeInteger(input.page)
      || !positiveSafeInteger(input.pageSize)
      || input.pageSize > 50) {
    throw failure('VALIDATION', 'Invalid pagination input');
  }
}

function validateId(id) {
  if (!nonemptyString(id)) throw failure('VALIDATION', 'Invalid invoice id');
}

function invoiceFromRow(row) {
  return {
    id: row.id,
    tenant: row.tenant,
    reservationId: row.reservation_id,
    amountCents: row.amount_cents,
    status: row.status,
    version: row.version,
  };
}

function canonicalIssue(input) {
  const event = input.event;
  return JSON.stringify({
    key: input.key,
    event: {
      id: event.id,
      tenant: event.tenant,
      sku: event.sku,
      quantity: event.quantity,
      amountCents: event.amountCents,
      status: event.status,
      version: event.version,
    },
  });
}

function canonicalTransition(input) {
  return JSON.stringify({
    key: input.key,
    id: input.id,
    expectedVersion: input.expectedVersion,
  });
}

export class BillingService {
  #db;

  constructor(filename) {
    this.#db = new DatabaseSync(filename);
    this.#db.exec('PRAGMA busy_timeout = 5000');
    this.#db.exec(`
      CREATE TABLE IF NOT EXISTS billing_invoices (
        creation_order INTEGER PRIMARY KEY AUTOINCREMENT,
        id TEXT NOT NULL UNIQUE,
        tenant TEXT NOT NULL,
        reservation_id TEXT NOT NULL,
        amount_cents INTEGER NOT NULL,
        status TEXT NOT NULL CHECK (status IN ('open', 'paid', 'refunded')),
        version INTEGER NOT NULL,
        UNIQUE (tenant, reservation_id)
      );
      CREATE INDEX IF NOT EXISTS billing_invoices_tenant_order
        ON billing_invoices (tenant, creation_order);
      CREATE TABLE IF NOT EXISTS billing_idempotency (
        tenant TEXT NOT NULL,
        operation TEXT NOT NULL,
        idempotency_key TEXT NOT NULL,
        canonical_input TEXT NOT NULL,
        result_json TEXT NOT NULL,
        PRIMARY KEY (tenant, operation, idempotency_key)
      );
    `);
  }

  #transaction(action) {
    this.#db.exec('BEGIN IMMEDIATE');
    try {
      const result = action();
      this.#db.exec('COMMIT');
      return result;
    } catch (error) {
      try {
        this.#db.exec('ROLLBACK');
      } catch {
        // Preserve the original failure if SQLite has already aborted the transaction.
      }
      throw error;
    }
  }

  #replayOrConflict(tenant, operation, key, canonical) {
    const row = this.#db.prepare(`
      SELECT canonical_input, result_json
      FROM billing_idempotency
      WHERE tenant = ? AND operation = ? AND idempotency_key = ?
    `).get(tenant, operation, key);
    if (!row) return undefined;
    if (row.canonical_input !== canonical) {
      throw failure('CONFLICT', 'Idempotency key was used with different input');
    }
    return JSON.parse(row.result_json);
  }

  #saveIdempotency(tenant, operation, key, canonical, result) {
    this.#db.prepare(`
      INSERT INTO billing_idempotency
        (tenant, operation, idempotency_key, canonical_input, result_json)
      VALUES (?, ?, ?, ?, ?)
    `).run(tenant, operation, key, canonical, JSON.stringify(result));
  }

  issue(actor, input) {
    authorizeMutation(actor);
    validateIssueInput(input);
    if (input.event.tenant !== actor.tenant) {
      throw failure('FORBIDDEN', 'Reservation event belongs to another tenant');
    }
    const canonical = canonicalIssue(input);
    return this.#transaction(() => {
      const replay = this.#replayOrConflict(actor.tenant, 'issue', input.key, canonical);
      if (replay !== undefined) return replay;

      const existing = this.#db.prepare(`
        SELECT 1 FROM billing_invoices WHERE tenant = ? AND reservation_id = ?
      `).get(actor.tenant, input.event.id);
      if (existing) throw failure('CONFLICT', 'Reservation already has an invoice');

      let id;
      do {
        id = randomUUID();
      } while (this.#db.prepare('SELECT 1 FROM billing_invoices WHERE id = ?').get(id));

      this.#db.prepare(`
        INSERT INTO billing_invoices
          (id, tenant, reservation_id, amount_cents, status, version)
        VALUES (?, ?, ?, ?, 'open', 1)
      `).run(id, actor.tenant, input.event.id, input.event.amountCents);
      const result = {
        id,
        tenant: actor.tenant,
        reservationId: input.event.id,
        amountCents: input.event.amountCents,
        status: 'open',
        version: 1,
      };
      this.#saveIdempotency(actor.tenant, 'issue', input.key, canonical, result);
      return result;
    });
  }

  #transition(actor, input, operation, requiredStatus, nextStatus) {
    authorizeMutation(actor);
    validateTransitionInput(input);
    const canonical = canonicalTransition(input);
    return this.#transaction(() => {
      const replay = this.#replayOrConflict(actor.tenant, operation, input.key, canonical);
      if (replay !== undefined) return replay;

      const row = this.#db.prepare(`
        SELECT id, tenant, reservation_id, amount_cents, status, version
        FROM billing_invoices WHERE tenant = ? AND id = ?
      `).get(actor.tenant, input.id);
      if (!row) throw failure('NOT_FOUND', 'Invoice not found');
      if (row.version !== input.expectedVersion || row.status !== requiredStatus) {
        throw failure('CONFLICT', 'Invoice cannot make this transition');
      }

      this.#db.prepare(`
        UPDATE billing_invoices SET status = ?, version = version + 1
        WHERE tenant = ? AND id = ?
      `).run(nextStatus, actor.tenant, input.id);
      const result = {
        ...invoiceFromRow(row),
        status: nextStatus,
        version: row.version + 1,
      };
      this.#saveIdempotency(actor.tenant, operation, input.key, canonical, result);
      return result;
    });
  }

  pay(actor, input) {
    return this.#transition(actor, input, 'pay', 'open', 'paid');
  }

  refund(actor, input) {
    return this.#transition(actor, input, 'refund', 'paid', 'refunded');
  }

  get(actor, id) {
    validateActor(actor);
    validateId(id);
    const row = this.#db.prepare(`
      SELECT id, tenant, reservation_id, amount_cents, status, version
      FROM billing_invoices WHERE tenant = ? AND id = ?
    `).get(actor.tenant, id);
    if (!row) throw failure('NOT_FOUND', 'Invoice not found');
    return invoiceFromRow(row);
  }

  list(actor, input) {
    validateActor(actor);
    validateListInput(input);
    const {total} = this.#db.prepare(`
      SELECT COUNT(*) AS total FROM billing_invoices WHERE tenant = ?
    `).get(actor.tenant);

    if (total === 0 || input.page > Math.ceil(total / input.pageSize)) {
      return {items: [], total};
    }
    const offset = (input.page - 1) * input.pageSize;
    const rows = this.#db.prepare(`
      SELECT id, tenant, reservation_id, amount_cents, status, version
      FROM billing_invoices
      WHERE tenant = ?
      ORDER BY creation_order
      LIMIT ? OFFSET ?
    `).all(actor.tenant, input.pageSize, offset);
    return {items: rows.map(invoiceFromRow), total};
  }

  close() {
    this.#db.close();
  }
}

